mapper.select:
SELECT c.id AS id, c.pay_order_id AS payOrderId, c.channel_chargeback_id AS channelChargebackId, c.mch_no AS mchNo, m.mch_name AS mchName, c.account_id AS accountId, c.if_code AS ifCode, c.chargeback_amount AS chargebackAmount, c.chargeback_currency AS chargebackCurrency, c.chargeback_reason_code AS chargebackReasonCode, c.chargeback_reason_desc AS chargebackReasonDesc, c.chargeback_type AS chargebackType, c.state AS state, c.evidence_due_at AS evidenceDueAt, c.evidence_submitted_at AS evidenceSubmittedAt, c.resolved_at AS resolvedAt, c.created_at AS createdAt FROM t_chargeback_record c LEFT JOIN t_mch_info m ON m.mch_no = c.mch_no
AND c.mch_no = #{mchNo}
AND c.account_id = #{accountId}
AND c.if_code = #{ifCode}
AND c.state = #{state}
AND c.created_at >= #{startTime}
AND c.created_at < #{endTime}
ORDER BY c.created_at DESC

SELECT COUNT(*) FROM t_chargeback_record
WHERE account_id = #{accountId}
  AND created_at >= #{startTime}
  AND created_at < #{endTime}
